import os, json, time, math
import numpy as np

RESULTS_DIR = 'storage/noesis/nmap/results'
OUT_SUMMARY = 'storage/noesis/nmap/cross_class_summary_v2_1_extended.json'
FREEZE_DIR  = 'storage/noesis/nmap/freezes'
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'
N = 26

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]
KEYS = [f'{tol}_K{K}' for tol in TOLS for K in K_GRID]
# For ΔJ plateaus at tol=1e-8
DELTA_KEYS = [('1e-08_K25','1e-08_K40'), ('1e-08_K40','1e-08_K60')]

def ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
        return c, r
    # Safe fallback (strictly feasible trivial pack)
    centers = []
    rad = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < N:
                centers.append([0.1+0.2*i, 0.1+0.15*j])
    return np.array(centers, float), np.full(N, rad, float)

def is_number(x):
    return isinstance(x, (int, float)) and not (isinstance(x, float) and (math.isnan(x) or math.isinf(x)))

def collect():
    # Global accumulators
    vals = {k: [] for k in KEYS}
    deltas = {f'{a}->{b}': [] for (a,b) in DELTA_KEYS}
    # Slices
    vals_idx_true = {k: [] for k in KEYS}
    vals_idx_false = {k: [] for k in KEYS}
    vals_cross_true = {k: [] for k in KEYS}
    vals_cross_false = {k: [] for k in KEYS}

    classes = 0
    idx_map_used = 0
    cross_present_cnt = 0

    for root, _, files in os.walk(RESULTS_DIR):
        for fn in files:
            if not fn.endswith('_compare_v2_1_refresh.json'):
                continue
            fpath = os.path.join(root, fn)
            try:
                data = json.load(open(fpath, 'r'))
            except Exception:
                continue

            classes += 1
            idx_flag = bool(data.get('index_map_applied', False))
            if idx_flag:
                idx_map_used += 1

            # Heuristic for native-cross presence flags in compare outputs
            cross_flag = False
            for key in ['native_cross_present','native_cross','crossings','native_crossings','native_crossing_examples']:
                if key in data and data[key]:
                    # if list, non-empty => True; if bool True => True; if dict with non-empty => True
                    v = data[key]
                    if isinstance(v, bool) and v:
                        cross_flag = True; break
                    if isinstance(v, (list, dict)) and len(v) > 0:
                        cross_flag = True; break
            if cross_flag:
                cross_present_cnt += 1

            j = data.get('jaccards', {})
            # Accumulate base J values
            for k in KEYS:
                v = j.get(k)
                if is_number(v):
                    vals[k].append(float(v))
                    (vals_idx_true if idx_flag else vals_idx_false)[k].append(float(v))
                    (vals_cross_true if cross_flag else vals_cross_false)[k].append(float(v))

            # Accumulate ΔJ at tol=1e-8 where available
            for (a,b) in DELTA_KEYS:
                va, vb = j.get(a), j.get(b)
                if is_number(va) and is_number(vb):
                    deltas[f'{a}->{b}'].append(float(vb) - float(va))

    return {
        'classes_seen': classes,
        'index_map_applied_frac': (idx_map_used / classes) if classes else 0.0,
        'native_cross_present_frac': (cross_present_cnt / classes) if classes else 0.0,
        'vals': vals,
        'vals_idx_true': vals_idx_true,
        'vals_idx_false': vals_idx_false,
        'vals_cross_true': vals_cross_true,
        'vals_cross_false': vals_cross_false,
        'deltas': deltas
    }

def stats(xs):
    if not xs:
        return {'n': 0, 'mean': None, 'median': None, 'min': None, 'max': None, 'p_ge_0_5': None, 'p_ge_0_66': None}
    arr = np.asarray(xs, float)
    return {
        'n': int(arr.size),
        'mean': float(arr.mean()),
        'median': float(np.median(arr)),
        'min': float(arr.min()),
        'max': float(arr.max()),
        'p_ge_0_5': float((arr >= 0.5).mean()),
        'p_ge_0_66': float((arr >= (2.0/3.0)).mean())
    }

def stats_delta(xs):
    if not xs:
        return {'n': 0, 'mean': None, 'median': None, 'min': None, 'max': None}
    arr = np.asarray(xs, float)
    return {
        'n': int(arr.size),
        'mean': float(arr.mean()),
        'median': float(np.median(arr)),
        'min': float(arr.min()),
        'max': float(arr.max())
    }

def construct_packing():
    c0, r0 = load_snapshot()

    C = collect()
    summary = {
        'generated_at': ts(),
        'k_grid': K_GRID,
        'tols': TOLS,
        'classes_seen': C['classes_seen'],
        'index_map_applied_frac': C['index_map_applied_frac'],
        'native_cross_present_frac': C['native_cross_present_frac'],
        'stats': {k: stats(v) for k, v in C['vals'].items()},
        'stats_idx_map_true': {k: stats(v) for k, v in C['vals_idx_true'].items()},
        'stats_idx_map_false': {k: stats(v) for k, v in C['vals_idx_false'].items()},
        'stats_native_cross_true': {k: stats(v) for k, v in C['vals_cross_true'].items()},
        'stats_native_cross_false': {k: stats(v) for k, v in C['vals_cross_false'].items()},
        'delta_stats': {k: stats_delta(v) for k, v in C['deltas'].items()},
        'notes': {
            'interpretation': 'ΔJ>0 across K at tol=1e-8 indicates rising overlap; plateau if means/medians shrink from K25->K40 to K40->K60. Slices reveal dependence on index-map and native-cross presence.',
            'limitations': 'Completeness-by-K not computed due to result schema variation; native-cross presence inferred heuristically from compare outputs.'
        }
    }

    write_json(OUT_SUMMARY, summary)
    write_json(os.path.join(FREEZE_DIR, f'cross_class_summary_v2_1_extended_{ts()}.json'), summary)

    # Return baseline with tiny shrink
    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)
